# owner: platform
"""Seating charts: students sorted into rows."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _name_key(student: Student) -> tuple:
    return (student.last_name, student.first_name)


def _full_name(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _row_line(number: int, group: list) -> str:
    names = [_full_name(item) for item in group]
    return f"Row {number}: " + " | ".join(names)


def _chunks(items: list, size: int) -> list:
    return [
        items[begin:begin + size]
        for begin in range(0, len(items), size)
    ]


def seating_rows(students: list, seats: int) -> list:
    """One line of text per row, sorted by last name."""
    if seats < 1 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_name_key)
    groups = _chunks(ordered, seats)
    lines = enumerate(groups, start=1)
    return [_row_line(*pair) for pair in lines]

